using System;using System.IO;using System.Linq;using System.Reflection;using System.Collections;using System.Collections.Generic;using UnityEngine;using Assets.Script.DynamicCards;
public static class MotionWork {public static void Run(){new GameObject("Motion symptom audit").AddComponent<MotionSymptomAudit>();}}
public class MotionSymptomAudit:MonoBehaviour {
const string W="C:/UnityProjects/LegacyGwent/work/DynamicCards/MotionRepair-20260910/MainTimeline/";
object F(object o,string n)=>o.GetType().GetField(n,BindingFlags.Instance|BindingFlags.NonPublic).GetValue(o);
void Save(DynamicCardView v,string name){var rt=(RenderTexture)F(v,"texture");if(rt==null)return;var old=RenderTexture.active;RenderTexture.active=rt;var t=new Texture2D(rt.width,rt.height,TextureFormat.RGBA32,false);t.ReadPixels(new Rect(0,0,rt.width,rt.height),0,0);t.Apply();RenderTexture.active=old;File.WriteAllBytes(W+name+".png",t.EncodeToPNG());Destroy(t);}
IEnumerator Start(){Directory.CreateDirectory(W);var log=new List<string>();for(int i=0;i<36;i++){foreach(var v in FindObjectsOfType<DynamicCardView>().Where(v=>F(v,"model")!=null)){var model=(GameObject)F(v,"model");var key=F(v,"artId")+"-"+F(v,"preview")+"-"+i;Save(v,key);foreach(var a in model.GetComponentsInChildren<Animator>(true))log.Add(key+" animator="+a.name+" time="+a.GetCurrentAnimatorStateInfo(0).normalizedTime+" clips="+string.Join(";",a.GetCurrentAnimatorClipInfo(0).Select(c=>c.clip.name+"/"+c.clip.length)));foreach(var s in model.GetComponentsInChildren<SkinnedMeshRenderer>(true))log.Add(key+" skin="+s.name+" enabled="+s.enabled+" quality="+s.quality+" offscreen="+s.updateWhenOffscreen); }yield return new WaitForSecondsRealtime(.5f);}File.WriteAllLines(W+"timeline.txt",log);Destroy(gameObject);}}
